/* Palette: deep navy, teal, coral, light gray, white */
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --highlight: #f5c542;
  --bar: #4a90d9;
  --bar-bg: #2a3a5a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 4px;
  color: var(--text);
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b8;
  margin-bottom: 20px;
}

.chart-container {
  background: var(--bar-bg);
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 16px;
}

.chart {
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  height: 180px;
  gap: 4px;
}

.bar-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
}

.bar {
  width: 100%;
  max-width: 40px;
  background: var(--bar);
  border-radius: 4px 4px 0 0;
  transition: height 0.2s ease, background 0.2s;
  min-height: 2px;
  position: relative;
}

.bar.longest {
  background: var(--highlight);
  box-shadow: 0 0 8px var(--highlight);
}

.bar-label {
  font-size: 0.75rem;
  color: #a0a0b8;
  margin-top: 4px;
  text-align: center;
  white-space: nowrap;
}

.average {
  font-size: 1.25rem;
  font-weight: 600;
  text-align: center;
  margin-bottom: 20px;
  color: var(--accent);
}

.inputs {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
}

.input-group {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.input-group label {
  font-size: 0.75rem;
  color: #a0a0b8;
  margin-bottom: 4px;
  text-align: center;
}

.input-group input {
  width: 100%;
  max-width: 60px;
  padding: 8px 4px;
  font-size: 1rem;
  text-align: center;
  border: 2px solid var(--primary);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-group input:hover {
  border-color: var(--bar);
}

.input-group input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

.input-group input:active {
  background: var(--primary);
}

/* Responsive */
@media (max-width: 480px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .inputs {
    grid-template-columns: repeat(4, 1fr);
  }
  .chart {
    height: 140px;
  }
  .bar-label {
    font-size: 0.65rem;
  }
}

@media (max-width: 360px) {
  .inputs {
    grid-template-columns: repeat(3, 1fr);
  }
}

[hidden] {
  display: none !important;
}

const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const MAX_HOURS = 12;

const chartEl = document.getElementById('chart');
const averageEl = document.getElementById('average');
const inputsEl = document.getElementById('inputs');

const values = new Array(7).fill(0);

function createInputs() {
  DAYS.forEach((day, i) => {
    const group = document.createElement('div');
    group.className = 'input-group';

    const label = document.createElement('label');
    label.textContent = day;
    label.htmlFor = `input-${i}`;

    const input = document.createElement('input');
    input.type = 'number';
    input.id = `input-${i}`;
    input.min = '0';
    input.max = '12';
    input.step = '0.5';
    input.value = '0';
    input.setAttribute('aria-label', `${day} hours slept`);

    input.addEventListener('input', (e) => {
      let val = parseFloat(e.target.value);
      if (isNaN(val)) val = 0;
      val = Math.min(MAX_HOURS, Math.max(0, val));
      values[i] = val;
      updateChart();
    });

    group.appendChild(label);
    group.appendChild(input);
    inputsEl.appendChild(group);
  });
}

function createBars() {
  chartEl.innerHTML = '';
  DAYS.forEach((day, i) => {
    const wrapper = document.createElement('div');
    wrapper.className = 'bar-wrapper';

    const bar = document.createElement('div');
    bar.className = 'bar';
    bar.id = `bar-${i}`;
    bar.style.height = '2px';

    const label = document.createElement('div');
    label.className = 'bar-label';
    label.textContent = day;

    wrapper.appendChild(bar);
    wrapper.appendChild(label);
    chartEl.appendChild(wrapper);
  });
}

function updateChart() {
  const maxVal = Math.max(...values);
  const longestIndex = values.indexOf(maxVal);

  values.forEach((val, i) => {
    const bar = document.getElementById(`bar-${i}`);
    if (!bar) return;
    const pct = (val / MAX_HOURS) * 100;
    bar.style.height = `${Math.max(2, pct)}%`;
    bar.classList.toggle('longest', i === longestIndex && maxVal > 0);
  });

  const sum = values.reduce((a, b) => a + b, 0);
  const avg = sum / 7;
  averageEl.textContent = `Weekly average: ${avg.toFixed(1)} h`;
}

createInputs();
createBars();
updateChart();
